Object.assign(paths,{edit:'M12 20h9 M16 3l5 5-12 12-5 1 1-5z M14 5l5 5',flask:'M9 3h6 M10 3v6L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3 M7 15h10',microscope:'M6 18h12 M10 21h4 M9 18v3 M12 5l4 4-4 4-4-4z M14 3l4 4 M16 13c4 0 4 5 0 5 M8 13H5v5',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',molecule:'M12 8v8 M5 5l7 3 7-3 M5 19l7-3 7 3 M5 5v14 M19 5v14 M2 3h6v5H2z M16 3h6v5h-6z M9 9h6v6H9z M2 17h6v5H2z M16 17h6v5h-6z',fullscreen:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5',bolt:'M13 2L4 14h7l-1 8 10-13h-7z',briefcase:'M8 7V4h8v3 M3 7h18v14H3z M3 12l9 4 9-4 M10 14h4v4h-4z',network:'M12 3v5 M5 18v-5h14v5 M12 8v10 M9 3h6v5H9z M2 18h6v4H2z M9 18h6v4H9z M16 18h6v4h-6z'});
