const NAMES=['Client Relationship Management','Improvement & Innovation','Cost Management','Information Management','Testing and Analysis','Laboratory Quality Standard System'];
const SHORT=['CRM','Innovation','Cost','Information','Testing','Lab Quality'];
const TABS=[['overview','grid','ภาพรวมการพัฒนา','Overview'],['directory','users','ทำเนียบบุคลากร','People'],['matrix','layers','แผนที่สมรรถนะ','Matrix'],['followup','target','ติดตามแผนพัฒนา','Action'],['upskill','book','Upskilling 2026','Learning'],['guide','info','หลักเกณฑ์และข้อมูล','Guide']];
TABS.splice(1,0,['input','edit','กรอกข้อมูล / อัปเดต','Input'],['peopleDB','briefcase','ทะเบียนรายชื่อแยก BU','Database']);
let printing=false,savedPage=0;
let source=window.TA_DATA||{}, records=[],ups=[],page=0,tab='overview',lab='',pl='',year='2026',query='',status='all',sourceLabel=source.source||'Google Sheets',loadedAt='',warnings=[];
function parseStatus(value){const raw=String(value??'').trim(),low=raw.toLowerCase();const complete=/\bcomplete\b/.test(low),plan=/\bplan\b/.test(low);const years=[...low.matchAll(/\b(20\d{2}|25\d{2}|\d{2})\b/g)].map(x=>{let y=Number(x[1]);return y<100?2000+y:y>=2500?y-543:y});return{raw,complete,plan,year:years.length?Math.max(...years):null,ambiguous:years.length>1,unknown:!!raw&&!complete&&!plan};}
function parseRows(rows,kind='core'){if(!Array.isArray(rows))throw Error('รูปแบบข้อมูลไม่ถูกต้อง');const h=rows.findIndex(r=>Array.isArray(r)&&r.some(c=>String(c).includes('First Name')));if(h<0)throw Error('ไม่พบหัวตาราง First Name (Local)');return rows.slice(h+1).filter(r=>r&&r[2]&&r[3]).map((r,i)=>{let p=String(r[5]??'').trim();const match=p.match(/\d+/);return{id:r[0]??i+1,salutation:r[1]||'',firstName:String(r[2]).trim(),lastName:String(r[3]).trim(),title:r[4]||'',pl:p==='คนงาน'?p:match?'PL '+Number(match[0]):'ไม่ระบุ',functionName:r[6]||'ไม่ระบุ',lab:r[7]||'ไม่ระบุ',remark:String(r[8]??''),cells:(kind==='up'?upColumns(rows[h]):[9,10,11,12,13,14]).map(j=>String(r[j]??'')),profileNote:String(r[32]??'')};});}
const isExit=e=>/ลาออก|เกษียณ|เกษียญ|ย้าย/.test(e.remark);
const newYear=e=>{if(!/พนักงานใหม่/.test(e.remark))return null;let m=e.remark.match(/20\d{2}/);return m?+m[0]:2026;};
const done=v=>{const p=parseStatus(v);return p.complete&&(!p.year||p.year<=Number(year));};
function evaluate(e){let rule=MATRIX[e.pl]||{must:[],should:[]},req=[...rule.must,...rule.should];let completed=req.filter(i=>done(e.cells[i-1])).length;let planned=req.filter(i=>!done(e.cells[i-1])&&parseStatus(e.cells[i-1]).plan&&(!parseStatus(e.cells[i-1]).year||parseStatus(e.cells[i-1]).year<=+year)).length;return{...rule,req,completed,total:req.length,planned,pct:req.length?completed/req.length*100:0,gap:req.length-completed,unplanned:req.length-completed-planned};}
// Use the FOLLOW/Employees roster for eligibility in every view, including Upskilling.
// Keep records and dbState complete: this is a display filter, never a deletion.
function active(e){const person=records.find(p=>String(p.id)===String(e.id))||e;return !isExit(person)&&!(newYear(person)&&newYear(person)>+year);}
function selectData(arr=records){return arr.filter(e=>active(e)&&(!lab||e.lab===lab)&&(!pl||e.pl===pl)&&(!query||`${e.firstName} ${e.lastName} ${e.title} ${e.lab} ${e.functionName}`.toLowerCase().includes(query.toLowerCase())));}
function aggregate(arr){let eligible=arr.filter(e=>evaluate(e).total>0),total=0,complete=0;eligible.forEach(e=>{const a=evaluate(e);total+=a.total;complete+=a.completed;});return{people:arr.length,eligible:eligible.length,total,complete,remaining:total-complete,pct:total?complete/total*100:0,finished:eligible.filter(e=>evaluate(e).gap===0).length,pending:eligible.filter(e=>evaluate(e).gap>0).length};}
const pct=v=>v.toFixed(1), num=v=>Number(v).toLocaleString('th-TH');
function options(values,current,title){return `<option value="">${title}</option>`+[...new Set(values)].sort().map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function toast(s,options){return window.TA_NOTIFY.show(s,options);}
function art(){return `<svg viewBox="0 0 270 145" fill="none"><ellipse cx="137" cy="126" rx="100" ry="10" fill="#dcd4ed"/><path d="M39 63l83-42 100 42-84 43z" fill="#b6a3e6"/><path d="M39 63v32l99 43v-32z" fill="#d7ccf0"/><path d="M138 106l84-43v31l-84 44z" fill="#9077c9"/><path d="M61 42l77-34 79 34-78 35z" fill="#7c60ba"/><path d="M104 62v29c21 16 49 16 70 0V62l-35 15z" fill="#9b80cb"/><path d="M138 43l66 4v40" stroke="#e4c883" stroke-width="3"/><circle cx="204" cy="90" r="5" fill="#e4c883"/><rect x="32" y="83" width="49" height="36" rx="8" fill="white" transform="rotate(-9 32 83)"/><path d="M47 98l6 5 12-15" stroke="#70aa95" stroke-width="3"/><circle cx="235" cy="37" r="17" fill="#fff9e9"/><path d="M229 38l4 4 8-11" stroke="#cca862" stroke-width="2"/><path d="M24 35v12 M18 41h12 M221 112v10 M216 117h10" stroke="#a98dcb" stroke-width="2"/></svg>`;}
function stat(label,value,unit,note,ico){return `<div class="stat"><div class="stat-icon">${icon(ico)}</div><div class="stat-label">${label}</div><div class="stat-value"><span class="counter" data-value="${esc(value)}">${value}</span><small>${unit}</small></div><div class="stat-note">${note}</div></div>`;}
function filters(){return `<div class="filters"><label>กรองข้อมูล</label><select id="lab" aria-label="ห้องปฏิบัติการ">${options(records.filter(active).map(e=>e.lab),lab,'ทุกห้องปฏิบัติการ')}</select><select id="pl" aria-label="ระดับ PL">${options(records.filter(active).map(e=>e.pl),pl,'ทุกระดับ PL')}</select><select id="year" aria-label="ปีสะสม"><option value="2026" ${year==='2026'?'selected':''}>สะสมถึงปี 2026</option><option value="2025" ${year==='2025'?'selected':''}>สะสมถึงปี 2025</option></select><button class="reset filter-reset" data-action="reset"><span class="filter-reset-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/></svg></span><span>ล้างตัวกรอง</span></button></div>`;}
function shell(){const t=TABS.find(x=>x[0]===tab);$('#app').innerHTML=`<div class="mobile-overlay" data-action="menu"></div><aside><div class="brand"><div class="brand-mark">${icon('layers')}</div><div>TA<span style="font-weight:400;color:#496875"> / </span>PULSE<small>LABORATORY INTELLIGENCE</small></div></div><p class="nav-label">WORKSPACE / 2026</p><nav>${TABS.map(x=>`<button data-tab="${x[0]}" class="${tab===x[0]?'active':''}">${icon(x[1])}${x[2]}${x[0]==='directory'?`<small>${records.filter(active).length}</small>`:''}</button>`).join('')}</nav><div class="side-note">${icon('star')}<b>People grow. Labs thrive.</b><p>พัฒนาคนให้พร้อม<br>ยกระดับห้องปฏิบัติการไปด้วยกัน</p></div><div class="side-footer"><div class="avatar">TA</div><div><strong>Laboratory Network</strong>Competency & Learning</div></div></aside><main><header><div class="crumb"><button class="menu-btn" data-action="menu" aria-label="เปิดเมนู">${icon('menu')}</button>Workspace <span> / &nbsp; ${esc(t[3])}</span></div><div class="header-right"><div class="live">${loadedAt?'อัปเดตจาก Google Sheets':dbReady?'ฐานข้อมูลในเครื่อง · โหมดทดลอง':'ข้อมูลจากไฟล์ Excel'}</div><div class="year-pill">${icon('clock').replace('class="icon"','class="icon" style="width:12px;height:12px;vertical-align:middle;margin-right:5px"')} Development year 2026</div><div class="avatar" style="width:30px;height:30px;font-size:10px">TA</div>${window.TA_CLOUD?.enabled?'<button class="btn" data-action="logout">ออกจากระบบ</button>':''}</div></header><div class="heading"><div><div class="eyebrow">PEOPLE. SKILLS. IMPACT.</div><h1>${tab==='overview'?'Talent Command Center':esc(t[2])}</h1><p>${tab==='overview'?'ภาพรวมการพัฒนาศักยภาพบุคลากรห้องปฏิบัติการ':({input:'บันทึกทะเบียนบุคลากรและผลพัฒนาในหน้าเดียว',peopleDB:'ฐานข้อมูลบุคลากรแยกตาม BU พร้อมประวัติการบันทึก',directory:'ทุกคน ทุกสมรรถนะ ในมุมมองเดียว',matrix:'มองเห็นความพร้อมและช่องว่างการพัฒนา',followup:'เปลี่ยนช่องว่างให้เป็นแผนพัฒนาที่ชัดเจน',upskill:'หลักสูตรเสริมทักษะจากชีต Upskilling 2026',guide:'รู้ที่มาของข้อมูล เข้าใจเกณฑ์ ก่อนนำผลไปใช้'})[tab]}</p></div><div class="actions"><button class="btn presentation-btn" data-action="presentation">${icon('fullscreen')} นำเสนอ</button>${window.TA_CLOUD?.enabled?'<button class="btn" data-action="refresh">'+icon('refresh')+' อ่านล่าสุด</button>':'<button class="btn" data-action="import">'+icon('upload')+' นำเข้า Excel</button>'}<button class="btn" data-action="print">${icon('print')} PDF / พิมพ์</button><button class="btn primary" data-action="export">${icon('export')} ส่งออก Excel</button></div></div>${!['guide','input','peopleDB'].includes(tab)?filters():''}<div id="content"></div><footer class="bottom"><span>TA PULSE / FROM POTENTIAL TO PERFORMANCE</span><span>แหล่งข้อมูล: ${esc(sourceLabel)} · ${loadedAt?esc(loadedAt):'ไฟล์ที่แนบมา'} </span></footer></main>`;renderContent();bindShell();}
let chartMode='tiles';
function labView(arr){const labs=[...new Set(arr.map(e=>e.lab))].map(l=>({lab:l,...aggregate(arr.filter(e=>e.lab===l))}));if(chartMode==='rank')return `<div class="lab-chart">${labs.sort((a,b)=>b.pct-a.pct).map((b,i)=>`<button class="bar-row" data-lab="${esc(b.lab)}" title="${esc(b.lab)}: ${b.complete}/${b.total}"><span><b class="rank-no">${String(i+1).padStart(2,'0')}</b>${esc(b.lab)}</span><div class="track"><div class="bar" style="width:${b.pct}%"></div></div><b>${b.total?pct(b.pct)+'%':'N/A'}</b></button>`).join('')||'<div class="empty">ไม่พบข้อมูล</div>'}</div>`;return `<div class="lab-tiles">${labs.sort((a,b)=>a.lab.localeCompare(b.lab)).map(b=>`<button class="lab-tile ${b.total&&b.pct<90?'attention':''}" data-lab="${esc(b.lab)}"><div class="lab-tile-top"><span class="lab-icon">${icon('flask')}</span><span class="lab-arrow">↗</span></div><div class="lab-name" title="${esc(b.lab)}">${esc(b.lab)}</div><div class="lab-signal"><strong>${b.total?Math.round(b.pct):'—'}<small>${b.total?'%':''}</small></strong><div class="lab-mini-ring" style="--pct:${b.pct}"></div></div><div class="lab-meta">${b.people} คน <span>${b.complete}/${b.total} รายการ</span></div></button>`).join('')||'<div class="empty">ไม่พบข้อมูลตามตัวกรอง</div>'}</div>`;}
function gauge(value){const radius=89,arc=Math.PI*radius,offset=arc*(1-value/100);return `<div class="gauge"><svg viewBox="0 0 250 150" role="img" aria-label="ความพร้อม ${pct(value)} เปอร์เซ็นต์"><defs><linearGradient id="gauge-color"><stop offset="0%" stop-color="#007e79"/><stop offset="60%" stop-color="#08d5a5"/><stop offset="100%" stop-color="#c3f960"/></linearGradient></defs><path d="M21 124 A104 104 0 0 1 229 124" fill="none" stroke="#ffffff18" stroke-width="1" stroke-dasharray="2 7"/><path d="M36 124 A89 89 0 0 1 214 124" fill="none" stroke="#294856" stroke-width="14"/><path d="M36 124 A89 89 0 0 1 214 124" fill="none" stroke="url(#gauge-color)" stroke-width="14" stroke-linecap="round" stroke-dasharray="${arc}" stroke-dashoffset="${offset}"/><text x="125" y="105" text-anchor="middle" class="gauge-number">${pct(value)}<tspan font-size="17">%</tspan></text><text x="125" y="126" text-anchor="middle" class="gauge-label">COMPETENCY READINESS</text><text x="27" y="148" class="gauge-tick">0%</text><text x="202" y="148" class="gauge-tick">100%</text></svg></div>`;}
const skillIcons=['network','bolt','briefcase','chart','microscope','shield'];
function skillCard(arr,n,i){const eligible=arr.filter(e=>evaluate(e).req.includes(i+1)),completed=eligible.filter(e=>done(e.cells[i])).length,percent=eligible.length?completed/eligible.length*100:0;return `<button class="skill-card skill-${i}" data-skill="${i}"><div class="skill-icon">${icon(skillIcons[i])}<span>${String(i+1).padStart(2,'0')}</span></div><div class="skill-top">CORE COMPETENCY <span>${icon('arrow')}</span></div><h4>${esc(n)}</h4><div class="track"><div class="bar" style="width:${percent}%"></div></div><footer><b>${eligible.length?pct(percent)+'%':'N/A'}</b><span>เหลือ ${eligible.length-completed} คน</span></footer></button>`;}
function skillDetail(index){const arr=selectData().filter(e=>evaluate(e).req.includes(index+1)),completed=arr.filter(e=>done(e.cells[index])).length,missing=arr.filter(e=>!done(e.cells[index]));$('#detail').innerHTML=`<div class="modal-head"><div><div class="eyebrow">COMPETENCY DEEP DIVE / 0${index+1}</div><h2>${esc(NAMES[index])}</h2><p>สำเร็จ ${completed} / ${arr.length} คนตามเกณฑ์ · รอพัฒนา ${missing.length} คน</p></div><button class="close" data-action="close" aria-label="ปิดรายละเอียด">×</button></div><div class="modal-body"><div class="skill-modal-progress"><div style="width:${arr.length?completed/arr.length*100:0}%"></div></div><p class="modal-note">${missing.length?'บุคลากรที่ยังพัฒนาไม่ครบสมรรถนะนี้ ตามตัวกรองปัจจุบัน':'ทุกคนที่มีเกณฑ์สมรรถนะนี้พัฒนาครบแล้ว'}</p>${missing.map(e=>`<div class="detail-person"><div><strong>${esc(e.firstName)} ${esc(e.lastName)}</strong><small>${esc(e.lab)} · ${esc(e.pl)} · ${esc(e.cells[index]||'ยังไม่ระบุแผน')}</small></div><button data-skill-person="${esc(e.id)}">ดูโปรไฟล์ ↗</button></div>`).join('')}</div>`;$('#detail').showModal();}
function renderContent(){const arr=selectData(),a=aggregate(arr);let html='';
if(tab==='overview'){html=`<div class="data-review-note">${icon('info')} ทะเบียนตั้งต้นอ้างอิง FOLLOW 2026 · มี 3 สถานะบุคลากรรอยืนยัน และความต่างระหว่างชีต 11 รายใน DataReview</div><section class="hero"><img class="hero-photo" src="assets/lab-hero.jpg" alt="นักวิทยาศาสตร์ทำงานกับปิเปตในห้องปฏิบัติการ"><div class="hero-index">LAB TALENT / ${year}</div><div class="hero-copy"><div class="eyebrow">THE PEOPLE BEHIND THE PRECISION</div><h2>Great science.<br><span>Starts with people.</span></h2><p>พัฒนาคนให้พร้อม สร้างทีมที่แข็งแกร่ง<br>มองเห็นทุกศักยภาพ และลงมือพัฒนาอย่างตรงจุด</p><div class="hero-actions"><button data-tab="followup">สำรวจโอกาสพัฒนา ${icon('arrow')}</button><span class="hero-label">6 COMPETENCIES. ONE CONNECTED TEAM.</span></div></div><div class="hero-caption">REAL PEOPLE. REAL SCIENCE.<small>ภาพประกอบโดย Julia Koblitz / Unsplash · ไม่ใช่ภาพแล็บ CPF</small></div></section><div class="stats">${stat('บุคลากรในฐานติดตาม',num(a.people),'คน',`<em>${a.eligible} คน</em> มีเกณฑ์ Must / Should`,'users')}${stat('ความพร้อมตามเกณฑ์',pct(a.pct),'%',`<em>${num(a.complete)}</em> / ${num(a.total)} รายการสำเร็จ`,'shield')}${stat('โฟกัสการพัฒนาถัดไป',num(a.pending),'คน',`${num(a.remaining)} รายการสมรรถนะคงเหลือ`,'bolt')}${stat('พัฒนาครบตามเกณฑ์',num(a.finished),'คน',`ครบ Must + Should สะสมถึงปี ${year}`,'target')}</div><section class="focus-band"><div class="focus-band-lead"><span class="focus-icon">${icon('bolt')}</span><div><div class="eyebrow">YOUR NEXT PRIORITY</div><h3>${a.pending?`อีก ${a.pending} คน ที่เราจะพัฒนาไปด้วยกัน`:'ทุกคนพัฒนาครบตามเกณฑ์แล้ว'}</h3><p>${a.remaining} สมรรถนะคงเหลือ · ${arr.reduce((n,e)=>n+evaluate(e).unplanned,0)} รายการยังไม่ระบุแผน</p></div></div><div class="focus-options"><button data-focus="pending">ดูรายการที่เหลือ ↗</button><button data-focus="noplan">โฟกัสคนที่ยังไม่มีแผน →</button></div></section><div class="grid-main"><section class="panel lab-panel"><div class="panel-head"><div><div class="eyebrow">CONNECTED LAB NETWORK</div><h3>ทุกแล็บ ในภาพเดียว</h3><p>คลิกห้องปฏิบัติการเพื่อดูบุคลากรและสมรรถนะ</p></div><div class="view-switch"><button data-chart="tiles" class="${chartMode==='tiles'?'active':''}" aria-label="แสดงแผนที่แล็บ">${icon('grid')}</button><button data-chart="rank" class="${chartMode==='rank'?'active':''}" aria-label="แสดงอันดับแล็บ">${icon('chart')}</button></div></div>${labView(arr)}</section><section class="panel readiness"><div class="panel-head"><div><div class="eyebrow">READINESS SIGNAL</div><h3>พร้อมไปต่อ อีกแค่ไหน?</h3><p>สัดส่วนสมรรถนะ Must + Should ที่สำเร็จ</p></div>${icon('target')}</div>${gauge(a.pct)}<div class="readiness-metrics"><div><span class="dot"></span>สำเร็จแล้ว<strong>${num(a.complete)}<small>รายการ</small></strong></div><div><span class="dot pale"></span>รอพัฒนา<strong>${num(a.remaining)}<small>รายการ</small></strong></div></div><div class="split-foot"><div>Must Have<b>${requirementPct(arr,'must')}</b></div><div>Should Have<b>${requirementPct(arr,'should')}</b></div></div><button class="readiness-cta" data-tab="matrix">เปิดแผนที่สมรรถนะ ${icon('arrow')}</button></section></div><div class="section-label"><h3>6 สมรรถนะ · 6 โอกาสเติบโต</h3><span>คลิกการ์ดเพื่อดูช่องว่างรายสมรรถนะ ↗</span></div><div class="skills-strip">${NAMES.map((n,i)=>skillCard(arr,n,i)).join('')}</div>${peoplePanel(arr.filter(e=>evaluate(e).gap>0).sort((x,y)=>evaluate(x).pct-evaluate(y).pct).slice(0,5),'Next moves / โอกาสพัฒนาที่ควรโฟกัส',false,true)}<div class="photo-credit">ภาพประกอบ: <a href="https://unsplash.com/photos/scientist-using-pipette-with-test-tubes-in-lab-RlOAwXt2fEA" target="_blank" rel="noopener">Julia Koblitz / Unsplash</a></div>`;}
if(['directory','followup','matrix'].includes(tab)){let filtered=arr.filter(e=>{let r=evaluate(e);return status==='all'||status==='done'&&r.total>0&&!r.gap||status==='pending'&&r.gap>0||status==='noplan'&&r.unplanned>0||status==='na'&&!r.total;});if(tab==='followup')filtered=filtered.filter(e=>evaluate(e).gap>0).sort((x,y)=>evaluate(y).unplanned-evaluate(x).unplanned||evaluate(x).pct-evaluate(y).pct);html=`<div class="stats ${tab==='followup'?'followup-summary':''}">${stat('บุคลากรที่แสดง',num(filtered.length),'คน',`จากฐานติดตาม ${num(arr.length)} คน`,'users')}${stat('สมรรถนะที่รอพัฒนา',num(a.remaining),'รายการ','นับเฉพาะ Must + Should','target')}${stat('ยังไม่ระบุแผน',num(arr.reduce((n,e)=>n+evaluate(e).unplanned,0)),'รายการ','ช่องว่างตามเกณฑ์ที่ยังไม่มีแผนถึงปีที่เลือก','clock')}${stat('ไม่มีเกณฑ์ประเมิน',num(arr.filter(e=>!evaluate(e).total).length),'คน','แสดง N/A แทนการตีความว่าไม่ผ่าน','info')}</div>${peoplePanel(filtered,tab==='matrix'?'Competency landscape':tab==='followup'?'รายการติดตามแผนพัฒนา':'ทำเนียบบุคลากร',tab==='matrix')}`;}
if(tab==='upskill')html=upskillView();if(tab==='guide')html=guideView();if(tab==='input')html=inputView();if(tab==='peopleDB')html=peopleDatabaseView();$('#content').innerHTML=html;bindContent();}
function requirementPct(arr,key){let total=0,c=0;arr.forEach(e=>evaluate(e)[key].forEach(i=>{total++;if(done(e.cells[i-1]))c++;}));return total?pct(c/total*100)+'%':'N/A';}
function peoplePanel(arr,title,matrix=false,compact=false){const size=Math.max(1,arr.length),pages=Math.ceil(arr.length/size);page=Math.min(page,Math.max(0,pages-1));const visible=compact?arr:arr.slice(page*size,(page+1)*size);return `<section class="panel"><div class="panel-head"><div><h3>${title}</h3><p>${compact?'ช่องว่างมากที่สุดตามสัดส่วนความสำเร็จ':'ข้อมูลบุคลากรที่อยู่ในฐานติดตาม · '+arr.length+' คน'}</p></div>${compact?'<button data-tab="followup">ดูรายการทั้งหมด ↗</button>':`<div class="search">${icon('search')}<input id="search" placeholder="ค้นหาชื่อ / ตำแหน่ง" aria-label="ค้นหาบุคลากร" value="${esc(query)}"></div>`}</div>${!compact?`<div class="chips">${[['all','ทั้งหมด'],['pending','ยังไม่ครบ'],['done','ครบตามเกณฑ์'],['noplan','ยังไม่มีแผน'],['na','ไม่มีเกณฑ์']].map(x=>`<button class="chip ${status===x[0]?'active':''}" data-status="${x[0]}">${x[1]}</button>`).join('')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>บุคลากร</th><th>ห้องปฏิบัติการ</th><th>ระดับ</th>${matrix?SHORT.map((n,i)=>`<th title="${NAMES[i]}">${n}</th>`).join(''):'<th>ความพร้อม</th><th>สถานะ</th>'}<th></th></tr></thead><tbody>${visible.map(e=>{const a=evaluate(e);return `<tr data-person="${esc(e.id)}"><td><button class="person-open" data-person="${esc(e.id)}"><div class="person"><div class="avatar">${esc(e.firstName.slice(0,1))}</div><div><strong>${esc(e.firstName)} ${esc(e.lastName)}</strong><small>${esc(e.functionName)}</small></div></div></button></td><td>${esc(e.lab)}</td><td><span class="pl-tag">${esc(e.pl)}</span></td>${matrix?e.cells.map((v,i)=>{let p=parseStatus(v),req=a.req.includes(i+1),complete=done(v),planned=p.plan&&(!p.year||p.year<=+year);return `<td><span class="matrix-cell ${complete?'done':planned?'plan':req?'gap':''}" title="${esc(NAMES[i]+': '+(v||'ยังไม่ระบุ')+(req?' · ตามเกณฑ์':' · เสริมทักษะ'))}">${complete?'✓':planned?'◷':req?'·':'—'}</span></td>`;}).join(''):`<td><div class="mini-progress"><div class="track"><div class="bar" style="width:${a.pct}%"></div></div><b>${a.total?Math.round(a.pct)+'%':'N/A'}</b></div></td><td><span class="status ${!a.total?'none':!a.gap?'done':''}">${!a.total?'ไม่มีเกณฑ์':!a.gap?'ครบตามเกณฑ์':`เหลือ ${a.gap} สมรรถนะ`}</span></td>`}<td style="color:#b0a0c5">↗</td></tr>`;}).join('')}</tbody></table>${!visible.length?'<div class="empty">ไม่พบข้อมูลตามตัวกรอง<br>ลองล้างตัวกรองหรือเปลี่ยนคำค้นหา</div>':''}</div><div class="table-footer"><span>${matrix?'✓ สำเร็จ · ◷ มีแผน · จุดสีชมพู = ช่องว่างตามเกณฑ์ · — นอกเกณฑ์':compact?'คลิกบุคลากรเพื่อดูรายละเอียดสมรรถนะ':'แสดง '+(arr.length?page*size+1:0)+'–'+Math.min((page+1)*size,arr.length)+' จาก '+arr.length+' คน'}</span>${!compact?`<div><button data-action="prev" ${!page?'disabled':''}>←</button> ${page+1} / ${pages||1} <button data-action="next" ${page>=pages-1?'disabled':''}>→</button></div>`:''}</div></section>`;}
function upskillView(){if(!ups.length)return '<div class="empty">ไฟล์นี้ไม่มีชีต Upskilling 2026<br>นำเข้าไฟล์ที่มีชีตนี้เพื่อแสดงหลักสูตร</div>';const all=selectData(ups),courses=upNames();let cs=courses.map((name,i)=>{let completed=all.filter(e=>done(e.cells[i])).length,plan=all.filter(e=>{let p=parseStatus(e.cells[i]);return !done(e.cells[i])&&p.plan&&(!p.year||p.year<=+year)}).length;return{name,completed,plan};});return `<div class="notice">หลักสูตร Upskilling แสดงเฉพาะรายการที่ระบุ Complete หรือ Plan ในชีตนี้ ช่องว่างหมายถึง “ยังไม่ระบุ” และไม่ใช้เกณฑ์ Must / Should ของ FOLLOW คำนวณ</div><div class="stats">${stat('บุคลากรในชีต',all.length,'คน','ฐานติดตามของ Upskilling แยกจาก FOLLOW','users')}${stat('เรียนสำเร็จ',cs.reduce((n,c)=>n+c.completed,0),'รายการ','คน × หลักสูตร สะสมถึงปีที่เลือก','check')}${stat('มีแผนเรียน',cs.reduce((n,c)=>n+c.plan,0),'รายการ','ยังไม่สำเร็จ และปีแผนไม่เกินปีที่เลือก','book')}${stat('หลักสูตรเสริมทักษะ',courses.length,'หลักสูตร','จากหัวตารางชีต Upskilling 2026','layers')}</div><section class="panel"><div class="panel-head"><div><h3>Learning portfolio</h3><p>ติดตามผลการเรียนรายหลักสูตร</p></div><span class="badge">Upskilling ${year}</span></div><div class="table-wrap"><table><thead><tr><th>หลักสูตร</th><th>สำเร็จ</th><th>มีแผน</th><th>ยังไม่ระบุ / ปีอื่น</th><th>สัดส่วนในรายการที่ระบุ</th></tr></thead><tbody>${cs.map(c=>`<tr><td style="white-space:normal;min-width:250px"><strong>${esc(c.name)}</strong></td><td><span class="status done">${c.completed} คน</span></td><td><span class="status">${c.plan} คน</span></td><td>${all.length-c.completed-c.plan} คน</td><td>${c.completed+c.plan?pct(c.completed/(c.completed+c.plan)*100)+'%':'N/A'}</td></tr>`).join('')}</tbody></table></div></section>`;}
function guideView(){const differences=records.flatMap(e=>{const u=ups.find(u=>u.firstName===e.firstName&&u.lastName===e.lastName);return u&&(u.remark!==e.remark||u.lab!==e.lab||u.pl!==e.pl)?[e.firstName+' '+e.lastName+': FOLLOW ['+e.lab+' / '+(e.remark||'ไม่มีหมายเหตุ')+'] · Upskilling ['+u.lab+' / '+(u.remark||'ไม่มีหมายเหตุ')+']']:[];});return `<section class="panel"><div class="panel-head"><div><h3>Data & methodology</h3><p>เกณฑ์เดิมที่สืบทอดจากโค้ด พร้อมที่มาของตัวเลข</p></div><span class="badge">TRANSPARENT BY DESIGN</span></div><div class="info-grid"><div class="info-box"><b>${records.filter(active).length}</b>บุคลากรในฐานติดตาม<br>ไม่นับลาออก เกษียณ และโอนย้าย</div><div class="info-box"><b>${ups.filter(active).length}</b>บุคลากรในฐาน Upskilling<br>ใช้สถานะบุคลากรจากทะเบียน FOLLOW เดียวกัน</div><div class="info-box"><b>6</b>สมรรถนะหลัก<br>ใช้ Must + Should ตามระดับ PL</div></div><div class="rules"><h4>เกณฑ์สมรรถนะตามระดับ PL</h4><div class="table-wrap"><table><thead><tr><th>ระดับ</th><th>Must Have (หมายเลขสมรรถนะ)</th><th>Should Have</th></tr></thead><tbody>${Object.entries(MATRIX).map(([p,r])=>`<tr><td>${p}</td><td>${r.must.join(', ')||'ไม่มี'}</td><td>${r.should.join(', ')||'ไม่มี'}</td></tr>`).join('')}</tbody></table></div><p>${NAMES.map((n,i)=>`${i+1}. ${n}`).join('<br>')}</p><h4>วิธีคำนวณที่ตรวจสอบได้</h4><p>ความคืบหน้า = จำนวนสมรรถนะ Must + Should ที่สำเร็จ ÷ จำนวนสมรรถนะ Must + Should ที่ต้องพัฒนาของบุคลากรทั้งหมดในตัวกรอง × 100 โดยนับผล Complete แบบสะสมถึงปีที่เลือก ไม่ใช้ค่า % สรุปเดิมใน Excel</p><p>รายที่หมายเหตุระบุลาออก เกษียณ เกษียญ หรือย้าย จะไม่อยู่ในฐานติดตาม เกณฑ์นี้อ้างอิงโค้ดเดิมและไม่ทราบวันที่ออก จึงไม่ใช่ยอดบุคลากรย้อนหลัง ณ สิ้นปี สำหรับพนักงานใหม่ที่ไม่ระบุปี ใช้ปี 2026 ตามบริบทไฟล์ ส่วนที่ระบุปีชัดเจนใช้ปีนั้น</p><p>ช่องว่างไม่ใช่ Plan · ผลสำเร็จที่ไม่มีปีนับเป็นสะสมโดยไม่ทราบปี · ข้อความมีหลายปีใช้ปีสูงสุดและแจ้งตรวจทาน · ระดับคนงานหรือไม่พบเกณฑ์แสดง N/A ไม่รวมเป็นผู้ไม่ผ่าน</p><h4>ข้อสังเกตข้อมูล ${warnings.length} รายการ</h4><p>${warnings.length?warnings.slice(0,30).map(esc).join('<br>'):'ไม่พบรูปแบบสถานะหรือระดับ PL ที่ต้องตรวจทาน'}</p><h4>ข้อมูลบุคลากรต่างกันระหว่างชีต ${differences.length} ราย</h4><p>แต่ละหน้าคำนวณจากชีตของตัวเอง ไม่มีการแก้หรือจับรวมสถานะอัตโนมัติ โปรดทบทวนรายชื่อต่อไปนี้ก่อนใช้อ้างอิงรวม</p><p>${differences.length?differences.map(esc).join('<br>'):'ไม่พบความต่างของห้องปฏิบัติการ ระดับ และหมายเหตุ'}</p><h4>จัดการแหล่งข้อมูล</h4><p>แหล่งปัจจุบัน: ${esc(sourceLabel)}<br>${window.TA_CLOUD?.enabled?'เวอร์ชันนี้อ่านและบันทึกใน Google Sheets กลางผ่าน Apps Script':'เวอร์ชันทดลองนี้บันทึกในฐานข้อมูลเบราว์เซอร์ เปิดกลับมาใช้ต่อได้เมื่อใช้เบราว์เซอร์เดิม'}</p><div class="actions"><button class="btn primary" data-action="import">${icon('upload')} นำเข้า Excel ใหม่</button><button class="btn" data-action="refresh">${icon('refresh')} คืนข้อมูล / อ่าน Sheets ใหม่</button></div><h4>การเชื่อม Google Sheets กลาง</h4><p>ชุดสำหรับ GitHub Pages เชื่อมกับ Google Sheets กลางผ่าน Apps Script หลัง Deploy backend แล้วใส่ URL /exec ใน config.js ผู้ใช้กรอกข้อมูลผ่านหน้าเว็บได้ โดยสิทธิ์อ่านและบันทึกกำหนดตามรหัสเข้าใช้งานและ BU</p><p>PDF ใช้การพิมพ์ของเบราว์เซอร์ พิมพ์รายการตามตัวกรองทุกหน้า เลือก Save as PDF และเปิด Background graphics เพื่อคงสีในการส่งออก</p></div></section>`;}
function bindShell(){for(const id of ['lab','pl','year'])$('#'+id)?.addEventListener('change',e=>{if(id==='lab')setPersonnelBU(e.target.value);if(id==='pl')pl=e.target.value;if(id==='year')year=e.target.value;page=0;shell();});}
function bindContent(){bindInput();$('#search')?.addEventListener('input',e=>{query=e.target.value;page=0;const start=e.target.selectionStart;renderContent();$('#search').focus();$('#search').setSelectionRange(start,start);});}
function detail(id){const e=records.find(x=>String(x.id)===String(id));if(!e)return;const a=evaluate(e);$('#detail').innerHTML=`<div class="modal-head"><div><div class="eyebrow">PERSONAL DEVELOPMENT PROFILE</div><h2>${esc(e.firstName)} ${esc(e.lastName)}</h2><p>${esc(e.lab)} / ${esc(e.pl)} / ${esc(e.functionName)}</p></div><button class="close" data-action="close" aria-label="ปิดรายละเอียด">×</button></div><div class="modal-body"><p class="modal-note">${esc(e.title)}<br>${a.total?`สำเร็จ ${a.completed} จาก ${a.total} สมรรถนะตามเกณฑ์ · ${pct(a.pct)}%`:'ไม่มีเกณฑ์ Must / Should สำหรับระดับนี้'}</p>${NAMES.map((name,i)=>{const v=e.cells[i],p=parseStatus(v),ok=done(v),required=a.must.includes(i+1)?'Must Have':a.should.includes(i+1)?'Should Have':'เสริมทักษะ';return `<div class="modal-row"><div>${i+1}. ${name}<label>${required} · ข้อความต้นฉบับ: ${esc(v||'ยังไม่ระบุ')}</label></div><span class="status ${ok?'done':!p.plan?'none':''}">${ok?'สำเร็จ '+(p.year||'ไม่ทราบปี'):p.plan?'แผน '+(p.year||'ไม่ทราบปี'):p.complete?'สำเร็จปี '+p.year:'ยังไม่ระบุ'}</span></div>`;}).join('')}<p class="modal-note">หมายเหตุ: ${esc(e.remark||'—')}<br>ผลสะสมถึงปี ${year} · แสดงตามข้อมูลต้นฉบับ</p></div>`;$('#detail').showModal();}
function exportData(){if(typeof XLSX==='undefined')return toast('ไม่สามารถโหลดตัวอ่าน Excel ได้');const wb=XLSX.utils.book_new();if(tab==='upskill'){const arr=selectData(ups);const names=upNames();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(arr.map(e=>({'ชื่อ':e.firstName,'นามสกุล':e.lastName,'PL':e.pl,'LAB':e.lab,...Object.fromEntries(e.cells.map((v,i)=>[names[i]||'Upskilling '+(i+1),v]))}))), 'Upskilling');}else{let arr=selectData();if(tab==='followup')arr=arr.filter(e=>evaluate(e).gap>0);if(['directory','matrix','followup'].includes(tab))arr=arr.filter(e=>{const a=evaluate(e);return status==='all'||status==='done'&&a.total>0&&!a.gap||status==='pending'&&a.gap>0||status==='noplan'&&a.unplanned>0||status==='na'&&!a.total;});const out=arr.map(e=>{let a=evaluate(e);return{'ลำดับอ้างอิง':e.id,'ชื่อ':e.firstName,'นามสกุล':e.lastName,'ตำแหน่ง':e.title,'PL':e.pl,'Function':e.functionName,'LAB':e.lab,'หมายเหตุ':e.remark,...Object.fromEntries(NAMES.map((n,i)=>[n,e.cells[i]])),'สำเร็จตามเกณฑ์':a.completed,'เกณฑ์ทั้งหมด':a.total,'รอพัฒนา':a.gap,'ยังไม่มีแผน':a.unplanned,'ความคืบหน้า (%)':a.total?Number(pct(a.pct)):'N/A','ผลสะสมถึงปี':Number(year)};});XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(out),'Follow-up');const a=aggregate(arr);XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{'ปี':year,'LAB':lab||'ทั้งหมด','PL':pl||'ทั้งหมด','บุคลากร':a.people,'มีเกณฑ์':a.eligible,'สำเร็จ':a.complete,'เกณฑ์ทั้งหมด':a.total,'% สำเร็จ':Number(pct(a.pct))}]),'Summary');}const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const link=document.createElement('a');link.href=url;link.download=`TA_Studio_${tab}_${year}.xlsx`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('ส่งออก Excel เรียบร้อยแล้ว');}
function audit(){warnings=[];for(const e of records){if(!MATRIX[e.pl])warnings.push(`${e.firstName} ${e.lastName}: ไม่พบเกณฑ์ ${e.pl}`);e.cells.forEach((v,i)=>{let p=parseStatus(v);if(p.unknown||p.ambiguous||p.complete&&!p.year)warnings.push(`${e.firstName} ${e.lastName} · ${SHORT[i]}: ${v} (โปรดตรวจทานปี / สถานะ)`);});}const keys=new Set();for(const e of records){let key=e.firstName+'|'+e.lastName;if(keys.has(key))warnings.push(`${e.firstName} ${e.lastName}: ชื่อซ้ำในข้อมูล กรุณาตรวจสอบ`);keys.add(key);}}
function setSource(next,label){const parsed=parseRows(next['FOLLOW 2026']);if(!parsed.length)throw Error('ไม่พบรายชื่อใน FOLLOW 2026');const u=next['Upskilling 2026']?parseRows(next['Upskilling 2026'],'up'):[];source=next;records=parsed;ups=u;sourceLabel=label;page=0;lab='';pl='';query='';audit();shell();}
function workbookRows(wb,sheetName,rows,kind){
 const parsed=parseRows(rows,kind),ws=wb.Sheets[sheetName],header=rows.find(r=>r?.some(c=>String(c).includes('First Name')))||[],columns=kind==='up'?upColumns(header):[9,10,11,12,13,14];
 for(const p of parsed){const row=rows.findIndex(r=>r&&String(r[2]||'').trim()===p.firstName&&String(r[3]||'').trim()===p.lastName);if(row<0)continue;
  const comments=col=>{const address=XLSX.utils.encode_cell({r:row,c:col});return (ws[address]?.c||[]).map(c=>'['+sheetName+'!'+address+(c.a?' · '+c.a:'')+']\n'+String(c.t||'')).join('\n\n');};
  p.details=columns.map(col=>({note:comments(col)}));
  const notes=Array.from({length:9},(_,col)=>comments(col)).filter(Boolean);if(p.profileNote)notes.push('['+sheetName+'!AG'+(row+1)+']\n'+p.profileNote);p.profileNote=notes.join('\n\n');
 }
 return parsed;
}
async function importFile(file){try{if(!file)return;if(typeof XLSX==='undefined')throw Error('ไม่สามารถโหลดตัวอ่าน Excel');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});const follow=wb.SheetNames.find(n=>n.trim().toUpperCase()==='FOLLOW 2026');if(!follow)throw Error('ไม่พบชีต FOLLOW 2026 กรุณาเลือกไฟล์ที่ถูกต้อง');const next={'FOLLOW 2026':XLSX.utils.sheet_to_json(wb.Sheets[follow],{header:1,defval:null})};const up=wb.SheetNames.find(n=>n.trim().toUpperCase()==='UPSKILLING 2026');if(up)next['Upskilling 2026']=XLSX.utils.sheet_to_json(wb.Sheets[up],{header:1,defval:null});loadedAt='';if(dbReady){const c=workbookRows(wb,follow,next['FOLLOW 2026'],'core'),u=up?workbookRows(wb,up,next['Upskilling 2026'],'up'):[];for(const person of c){const alt=u.find(p=>p.firstName===person.firstName&&p.lastName===person.lastName);person.profileNote=[person.profileNote,alt?.profileNote].filter(Boolean).join('\n\n');}await TA_DB.replaceDataset(c,u,file.name,next['Upskilling 2026']?.find(r=>r.some(c=>String(c).includes('First Name'))));source=next;await hydrateDatabase();}else setSource(next,file.name);toast(`นำเข้าสำเร็จ ${records.length} รายการ · บันทึกลงฐานข้อมูลในเครื่องแล้ว`);}catch(e){toast('นำเข้าไม่สำเร็จ: '+e.message);}finally{$('#upload').value='';}}
function refresh(){if(typeof google!=='undefined'&&google.script?.run){toast('กำลังอ่านข้อมูลล่าสุด…');google.script.run.withSuccessHandler(r=>{try{if(!r.success)throw Error(r.error||'อ่านข้อมูลไม่สำเร็จ');loadedAt=new Date().toLocaleString('th-TH');setSource(r.sheets,r.source||'Google Sheets');toast('อัปเดตข้อมูลล่าสุดเรียบร้อย');}catch(e){toast(e.message,{type:'error'});}}).withFailureHandler(e=>toast('อ่านข้อมูลไม่สำเร็จ: '+e.message)).getDashboardData();}else{hydrateDatabase().then(()=>toast('อ่านข้อมูลที่บันทึกไว้ในเครื่องแล้ว')).catch(e=>toast(e.message,{type:'error'}));}}
// Personnel database and input UI. The data lives on this device until backed up.
let dbReady=false,dbState={people:[],core:[],upskill:[],meta:[],history:[],bus:[]},editingId='',dbBU='',dbQuery='';
const DEFAULT_UP=['พื้นฐาน molecular / เทคนิค Real time PCR','พื้นฐานสิทธิบัตรและอนุสิทธิบัตร','ข้อกำหนดและการตรวจติดตาม ISO/IEC 17025','การประเมินค่าความไม่แน่นอนของการวัดในการวิเคราะห์ทางเคมี','ISO 6887','การเขียนสิทธิบัตรและอนุสิทธิบัตร','Advance excel','AI for Excel'];
// Original workbook stores six courses in J:O and the two added courses in Z:AA.
// Cloud/export headers are compact and may contain further courses after the first eight.
function upColumns(header=[]){return /ALL Competency/i.test(String(header[15]||''))?[9,10,11,12,13,14,25,26]:Array.from({length:Math.max(DEFAULT_UP.length,header.length-9)},(_,i)=>i+9);}
function upNames(){const h=source['Upskilling 2026']?.find(r=>r.some(c=>String(c).includes('First Name')))||[];return upColumns(h).map((j,i)=>String(h[j]||DEFAULT_UP[i]||'Upskilling '+(i+1)).trim());}
function padLearning(record,count){return{...record,cells:Array.from({length:count},(_,i)=>record?.cells?.[i]||''),details:Array.from({length:count},(_,i)=>({...record?.details?.[i]}))};}
async function hydrateDatabase(){dbState=await TA_DB.load();const meta=dbState.meta.find(x=>x.id==='source');records=dbState.people.map(p=>({...p,cells:dbState.core.find(c=>c.id===p.id)?.cells||Array(6).fill('')}));if(meta?.headers)source['Upskilling 2026']=[meta.headers];dbState.upskill=dbState.upskill.map(p=>padLearning(p,upNames().length));ups=dbState.upskill.map(p=>({...p}));sourceLabel=meta?.label||sourceLabel;dbReady=true;if(window.TA_CLOUD?.enabled)loadedAt=new Date().toLocaleString('th-TH');audit();shell();}
async function bootstrapDatabase(){try{if(!window.indexedDB)throw Error('เบราว์เซอร์ไม่รองรับ IndexedDB');await TA_DB.seed(records,ups,sourceLabel,source['Upskilling 2026']?.find(r=>r.some(c=>String(c).includes('First Name'))));await hydrateDatabase();}catch(e){toast('ยังบันทึกฐานข้อมูลไม่ได้: '+e.message);}}
function field(label,name,value='',type='text',required=false,extra=''){if(name==='profileNote'||/Note\d+$/.test(name))return `<label class="field source-note-field"><span>${label}</span><textarea name="${name}" rows="3" maxlength="20000">${esc(value)}</textarea></label>`;return `<label class="field"><span>${label}${required?'<em>*</em>':''}</span><input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function selectField(label,name,values,value='',required=false){return `<label class="field"><span>${label}${required?'<em>*</em>':''}</span><select name="${name}" ${required?'required':''}><option value="">เลือก${label}</option>${values.map(v=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function inputView(){if(!dbReady)return '<div class="empty">กำลังเตรียมฐานข้อมูลรายชื่อ…</div>';const p=dbState.people.find(p=>p.id===editingId)||{},c=dbState.core.find(c=>c.id===editingId)||{},u=dbState.upskill.find(c=>c.id===editingId)||{},bus=[...new Set([...dbState.bus.map(b=>b.name),...records.filter(active).map(e=>e.lab)])].sort();let employ=isExit({...p,remark:p.remark||''})?(/ลาออก/.test(p.remark)?'ลาออก':/ย้าย/.test(p.remark)?'ย้ายสังกัด':'เกษียณ'):/พนักงานใหม่/.test(p.remark||'')?'พนักงานใหม่':'ปฏิบัติงาน';return `<div class="input-top"><div><span class="input-chip">${icon('users')} PERSONNEL & LEARNING RECORD</span><h2>${editingId?'อัปเดตเส้นทางการพัฒนา':'เพิ่มคนใหม่ สร้างโอกาสเติบโต'}</h2><p>กรอกทะเบียนบุคลากร เลือก BU และบันทึกผลพัฒนาทั้ง 2 กลุ่มในหน้าเดียว</p></div><div class="database-status"><span class="dot"></span>${window.TA_CLOUD?.enabled?'เชื่อมฐานกลาง Google Sheets':'บันทึกในเครื่องนี้เมื่อกดบันทึก'}</div></div><div class="edit-picker"><div><label for="profile-picker">ค้นหารายชื่อเพื่อแก้ไข</label><input id="profile-picker" list="person-options" placeholder="พิมพ์ชื่อ / เลือกบุคลากร" autocomplete="off" value="${editingId?esc(p.firstName+' '+p.lastName+' · '+p.lab):''}"><datalist id="person-options">${dbState.people.filter(active).map(p=>`<option value="${esc(p.firstName+' '+p.lastName+' · '+p.lab)}"></option>`).join('')}</datalist></div><button class="btn primary" data-action="new-person">${icon('users')} เพิ่มบุคลากรใหม่</button></div><form id="person-form"><section class="input-section"><div class="input-section-title"><span class="step-number blue">01</span><div><h3>ทะเบียนบุคลากร</h3><p>รายชื่อ ตำแหน่ง สายงาน และ BU ที่ใช้เชื่อมกับผลพัฒนา</p></div><span class="required-hint">* ข้อมูลจำเป็น</span></div><div class="form-grid">${field('รหัสพนักงาน (ถ้ามี)','employeeCode',p.employeeCode||'','text',false,'maxlength="40"')}${selectField('คำนำหน้า','salutation',['นาย','นาง','นางสาว','ไม่ระบุ'],p.salutation||'ไม่ระบุ')}${field('ชื่อ','firstName',p.firstName||'','text',true,'maxlength="120"')}${field('นามสกุล','lastName',p.lastName||'','text',true,'maxlength="120"')}${selectField('BU / ห้องปฏิบัติการ','lab',bus,p.lab||lab,true)}${selectField('สายงาน / Function','functionName',[...new Set([...records.map(r=>r.functionName),'Chemistry','Microbiology','QSS','Calibration','Physical & Sensory','ผู้บริหาร'])].sort(),p.functionName||'',true)}${field('ตำแหน่ง','title',p.title||'','text',true)}${selectField('ระดับ PL','pl',Object.keys(MATRIX),p.pl||'PL 1',true)}${selectField('สถานะบุคลากร','employment',['ปฏิบัติงาน','พนักงานใหม่','ลาออก','เกษียณ','ย้ายสังกัด'],employ,true)}${field('ปีที่เริ่มเป็นพนักงานใหม่','newYear',newYear({...p,remark:p.remark||''})||'','number',false,'min="2020" max="2100"')}${field('หมายเหตุบุคลากร','profileNote',p.profileNote||(!/ลาออก|ย้าย|เกษียณ|เกษียญ|พนักงานใหม่/.test(p.remark||'')?p.remark||'':''),'text',false,'maxlength="1000"')}</div><div class="field-help">${icon('info')} ไม่มีรหัสพนักงานก็เพิ่มได้ ระบบสร้างรหัสอ้างอิงภายในให้ และตรวจชื่อหรือรหัสซ้ำก่อนบันทึก</div></section><section class="input-section"><div class="input-section-title"><span class="step-number orange">02</span><div><h3>ผลพัฒนาสมรรถนะหลัก</h3><p>รายการตาม Matrix · ปรับตาม PL ที่เลือก</p></div><span class="badge">CORE COMPETENCY</span></div>${learningInputs(NAMES,c.cells||[],c.details||[],'core',p.pl||'PL 1')}</section><section class="input-section"><div class="input-section-title"><span class="step-number green">03</span><div><h3>ผลเรียน Upskilling</h3><p>หลักสูตรเสริมทักษะ แยกจากสมรรถนะหลัก ไม่ตีความช่องว่างว่าเป็นแผน</p></div><span class="badge">LEARNING</span></div>${learningInputs(upNames(),u.cells||[],u.details||[],'up',p.pl||'PL 1')}</section><div class="save-bar"><div><strong>${editingId?esc(p.firstName+' '+p.lastName):'บุคลากรใหม่'}</strong><small>บันทึกแล้ว Dashboard และทะเบียนรายชื่อจะอัปเดตตามข้อมูล</small></div><div class="actions"><button type="button" class="btn" data-tab="peopleDB">เปิดทะเบียนรายชื่อ</button><button type="submit" class="btn primary save-button">${icon('check')} บันทึกข้อมูลทั้งหมด</button></div></div><div id="save-error" role="alert"></div></form><div class="local-note">${icon('info')} ${window.TA_CLOUD?.enabled?'ข้อมูลจะบันทึกลง Google Sheets กลาง และแสดงให้ผู้มีสิทธิ์ใน BU เดียวกันเมื่ออ่านข้อมูลล่าสุด':'โหมดทดลอง: ฐานข้อมูลอยู่ในเบราว์เซอร์นี้ สำรอง JSON เพื่อย้ายเครื่อง ข้อมูลยังไม่ซิงก์ให้ผู้ใช้อื่น'}</div>`;}
function learningRelevant(prefix,index,level,cell){const rule=MATRIX[level]||{must:[],should:[]};if(prefix==='core')return rule.must.includes(index+1)||rule.should.includes(index+1);const status=parseStatus(cell);return !!(status.plan||status.complete);}
function refreshLearningMatrix(root,level){const group=root.querySelector('[data-learning-group="core"]');if(!group)return;const rule=MATRIX[level]||{must:[],should:[]},main=group.querySelector('.learning-relevant'),extra=group.querySelector('.learning-extra-list'),items=[...group.querySelectorAll('.learning-item')].sort((a,b)=>+a.dataset.learningIndex-+b.dataset.learningIndex);let count=0;items.forEach(item=>{const i=+item.dataset.learningIndex,relevant=learningRelevant('core',i,level,'');item.querySelector('[data-core-kind]').textContent=rule.must.includes(i+1)?'Must Have':rule.should.includes(i+1)?'Should Have':'เสริมทักษะ';(relevant?main:extra).appendChild(item);if(relevant)count++;});group.querySelector('.learning-relevant-count').textContent='เกี่ยวข้องกับบุคลากรนี้ '+count+' รายการ';group.querySelector('.learning-extra-count').textContent=items.length-count;group.querySelector('.learning-additional').hidden=count===items.length;}
function revealLearningItem(item){if(!item)return;item.open=true;const extra=item.closest('.learning-additional');if(extra)extra.open=true;}
function learningInputs(names,cells,details,prefix,level){const rule=MATRIX[level]||{must:[],should:[]};const rows=names.map((n,i)=>{const p=parseStatus(cells[i]),d=details[i]||{},kind=prefix==='core'?(rule.must.includes(i+1)?'Must Have':rule.should.includes(i+1)?'Should Have':'เสริมทักษะ'):'Upskilling',state=p.complete?'done':p.plan?'planned':'empty',statusLabel=p.complete?'สำเร็จ':p.plan?'มีแผน':'ยังไม่ระบุ';return `<details class="learning-item" data-learning-prefix="${prefix}" data-learning-index="${i}" data-learning-state="${state}"><summary><span class="learning-item-number">${String(i+1).padStart(2,'0')}</span><span class="learning-item-heading"><strong>${esc(n)}</strong><span class="learning-kind" ${prefix==='core'?`data-core-kind="${i+1}"`:''}>${kind}</span></span><span class="learning-summary-status">${statusLabel}${p.year?' · '+esc(p.year):''}</span><span class="learning-expand" aria-hidden="true">⌄</span></summary><div class="learning-fields">${selectField('สถานะ',prefix+'Status'+i,['ยังไม่ระบุ','มีแผน','สำเร็จ'],statusLabel)}${field('ปี (ค.ศ.)',prefix+'Year'+i,p.year||'','number',false,'min="2000" max="2100"')}${field('วันที่เรียนสำเร็จ',prefix+'Date'+i,d.completedDate||'','date')}${field('ลิงก์หลักฐาน / ใบรับรอง',prefix+'Evidence'+i,d.evidence||'','url',false,'placeholder="https://…"')}${field('หมายเหตุการพัฒนา',prefix+'Note'+i,d.note||'','text',false,'maxlength="1000"')}</div></details>`;});const included=names.map((_,i)=>learningRelevant(prefix,i,level,cells[i]));return `<div class="learning-form learning-accordion" data-learning-group="${prefix}"><p class="learning-instruction">${prefix==='core'?'เฉพาะ Must Have และ Should Have ตาม Matrix ของ PL ที่เลือก':'เฉพาะหลักสูตรที่มีแผนหรือผลเรียนของบุคลากรนี้ · ช่องว่างไม่ถือว่าต้องเรียน'}<br>คลิกหัวข้อเพื่อบันทึกผล</p><p class="learning-relevant-count">เกี่ยวข้องกับบุคลากรนี้ ${included.filter(Boolean).length} รายการ</p><div class="learning-relevant">${rows.filter((_,i)=>included[i]).join('')}</div><details class="learning-additional" ${included.every(Boolean)?'hidden':''}><summary>การเรียนรู้เพิ่มเติม / ประวัตินอกเกณฑ์ <span class="learning-extra-count">${included.filter(x=>!x).length}</span> รายการ ▾</summary><p>ไม่รวมเป็นรายการที่ต้องเรียนตามเกณฑ์ · เปิดเพื่อเพิ่มแผนหรือดูประวัติเดิม</p><div class="learning-extra-list">${rows.filter((_,i)=>!included[i]).join('')}</div></details></div>`;}
function updateLearningSummary(target){const item=target.closest('.learning-item');if(!item)return;const prefix=item.dataset.learningPrefix,i=item.dataset.learningIndex,status=item.querySelector(`[name="${prefix}Status${i}"]`).value,yr=item.querySelector(`[name="${prefix}Year${i}"]`).value;item.dataset.learningState=status==='สำเร็จ'?'done':status==='มีแผน'?'planned':'empty';item.querySelector('.learning-summary-status').textContent=status+(yr?' · '+yr:'');}
document.addEventListener('input',e=>{if(e.target.closest?.('.learning-item'))updateLearningSummary(e.target);});
document.addEventListener('change',e=>{if(e.target.closest?.('.learning-item'))updateLearningSummary(e.target);});
document.addEventListener('invalid',e=>{const item=e.target.closest?.('.learning-item');revealLearningItem(item);},true);
function peopleDatabaseView(){if(!dbReady)return '<div class="empty">กำลังเตรียมทะเบียนรายชื่อ…</div>';const people=dbState.people.filter(p=>active(p)&&matchesPersonnelSearch(p,query)&&(!dbBU||p.lab===dbBU)&&(!dbQuery||`${p.firstName} ${p.lastName} ${p.employeeCode||''} ${p.title}`.toLowerCase().includes(dbQuery.toLowerCase()))),bus=[...new Set(dbState.bus.map(x=>x.name))].sort();return `<div class="db-banner"><div><div class="eyebrow">PEOPLE DATABASE</div><h2>ตั้งค่าบุคลากรและบันทึกผล</h2><p>เพิ่มและแก้ไขรายชื่อ ตำแหน่ง BU และผลพัฒนาได้ในหน้านี้</p></div><button class="btn" data-action="new-person">${icon('users')} เพิ่มบุคลากร</button></div><div class="bu-grid"><button class="bu-card bu-all ${!dbBU?'active':''}" data-bu="" aria-pressed="${!dbBU}"><span class="bu-top"><span class="bu-monogram">${icon('network')}</span><span class="bu-name">ทุก BU<small>ภาพรวมทะเบียนบุคลากร</small></span></span><strong>${dbState.people.filter(active).length}<small>คน</small></strong><span class="bu-card-footer"><span>${!dbBU?'✓ กำลังแสดง':'ดูบุคลากรทั้งหมด'}</span><span>↗</span></span></button>${bus.map((b,i)=>`<button class="bu-card ${dbBU===b?'active':''}" data-bu="${esc(b)}" aria-pressed="${dbBU===b}" style="--bu-accent:${['#507cba','#8362ae','#308b83','#b17c40'][i%4]};--bu-pale:${['#eef4ff','#f5effb','#edf8f5','#fff6e9'][i%4]}"><span class="bu-top"><span class="bu-monogram">${esc(b.split(/[ /]+/).map(x=>x[0]).join('').slice(0,3).toUpperCase()+(b.includes('/')?'':b.slice(1,2).toUpperCase()))}</span><span class="bu-name">${esc(b)}<small>ห้องปฏิบัติการ / BU</small></span></span><strong>${dbState.people.filter(p=>active(p)&&p.lab===b).length}<small>คน</small></strong><span class="bu-card-footer"><span>${dbBU===b?'✓ กำลังแสดง':'ดูรายชื่อบุคลากร'}</span><span>↗</span></span></button>`).join('')}<button class="bu-card add-bu" data-action="add-bu"><span class="bu-add-symbol">＋</span><span class="bu-add-title">เพิ่ม BU</span><small>เพิ่มหน่วยงานในทะเบียน</small></button></div><section class="panel"><div class="panel-head"><div><h3>ทะเบียนรายชื่อ ${dbBU?' / '+esc(dbBU):'ทุก BU'}</h3><p>แสดงเฉพาะบุคลากรในฐานติดตาม · ไม่รวมลาออก เกษียณ และโอนย้าย</p></div><div class="search">${icon('search')}<input id="db-search" aria-label="ค้นหาทะเบียนพนักงาน" placeholder="ชื่อ / รหัส / ตำแหน่ง" value="${esc(dbQuery)}"></div></div><div class="db-tools"><span>${people.length} รายการ</span><div class="actions"><button class="btn" data-action="backup-db">${icon('download')} สำรอง JSON</button><button class="btn" data-action="restore-db">${icon('upload')} กู้คืน JSON</button><button class="btn" data-action="import">นำเข้า Excel</button></div></div><div class="table-wrap"><table><thead><tr><th>บุคลากร / รหัสพนักงาน</th><th>BU</th><th>สายงาน</th><th>ระดับ</th><th>สถานะ</th><th>การพัฒนา</th><th>จัดการ</th></tr></thead><tbody>${people.map(p=>{const e=records.find(e=>e.id===p.id),a=e?evaluate(e):{pct:0,total:0},exit=isExit(p);return `<tr><td><div class="person"><div><strong>${esc(p.firstName+' '+p.lastName)}</strong><small>${esc(p.employeeCode||'ยังไม่ระบุรหัสพนักงาน')}</small></div></div></td><td>${esc(p.lab)}</td><td>${esc(p.functionName)}</td><td><span class="pl-tag">${esc(p.pl)}</span></td><td><span class="status ${exit?'none':'done'}">${esc(exit?p.remark:/พนักงานใหม่/.test(p.remark)?'พนักงานใหม่':'ปฏิบัติงาน')}</span></td><td>${!exit&&a.total?pct(a.pct)+'%':'—'}</td><td><button class="edit-person" data-edit="${esc(p.id)}">${icon('edit')} แก้ไข</button></td></tr>`;}).join('')}</tbody></table>${people.length?'':'<div class="empty">ไม่พบรายชื่อ</div>'}</div><div class="table-footer"><span>คลิกแก้ไขเพื่อเปิดผลพัฒนาและหลักฐานของแต่ละคน</span><span>อัปเดตล่าสุด: ${dbState.history.length?esc(new Date([...dbState.history].sort((a,b)=>b.at.localeCompare(a.at))[0].at).toLocaleString('th-TH')):'ข้อมูลตั้งต้นจาก Excel'}</span></div></section><section class="panel history-panel"><div class="panel-head"><div><h3>ประวัติการบันทึกในเครื่องนี้</h3><p>เก็บชื่อรายการและเวลาที่บันทึก ไม่ลบทับประวัติเมื่อแก้บุคลากร</p></div></div><div class="history-list">${[...dbState.history].sort((a,b)=>b.at.localeCompare(a.at)).slice(0,12).map(h=>`<div><span class="history-dot"></span><strong>${esc(h.name)}</strong><small>${esc(h.summary||'บันทึกข้อมูล')}</small><time>${esc(new Date(h.at).toLocaleString('th-TH'))}</time></div>`).join('')||'<p>ยังไม่มีการแก้ไขข้อมูล</p>'}</div></section><div class="local-note">${icon('info')} ${window.TA_CLOUD?.enabled?'ฐานกลาง Google Sheets · แสดงข้อมูลตามสิทธิ์ BU · ไม่เก็บรหัสเข้าใช้งานไว้ใน GitHub':'โหมดทดลองในอุปกรณ์นี้ · สำรอง JSON เพื่อย้ายเครื่องหรือกู้คืน'}</div>`;}
function openPersonnelDialog(id=''){
 if(!dbReady)return toast('กรุณารอฐานข้อมูล');
 const previousId=editingId;editingId=id;
 const person=dbState.people.find(p=>p.id===id);
 const markup=inputView();
 const start=markup.indexOf('<form id="person-form">'),end=markup.indexOf('</form>',start)+7;
 const formHtml=markup.slice(start,end).replace('<form id="person-form">','<form id="person-form" data-personnel-modal="true">').replace('<button type="button" class="btn" data-tab="peopleDB">เปิดทะเบียนรายชื่อ</button>','<button type="button" class="btn" data-action="close">ยกเลิก</button>');
 const dialog=$('#detail');dialog.classList.add('personnel-editor');
 dialog.innerHTML=`<div class="modal-head"><div><div class="eyebrow">ตั้งค่าบุคลากร</div><h2>${person?'แก้ไข '+esc(person.firstName+' '+person.lastName):'เพิ่มบุคลากร'}</h2><p>แก้ไขและบันทึกในหน้านี้ · ข้อมูลจะอัปเดตในทะเบียน</p></div><button class="close" data-action="close" aria-label="ยกเลิกและปิด">×</button></div><div class="personnel-editor-body">${formHtml}</div>`;
 if(!id&&dbBU)dialog.querySelector('[name="lab"]').value=dbBU;
 dialog.querySelector('#person-form').addEventListener('submit',savePersonForm);
 dialog.querySelector('[name="pl"]').addEventListener('change',e=>refreshLearningMatrix(dialog,e.target.value));
 if(dialog._personnelCloseHandler)dialog.removeEventListener('close',dialog._personnelCloseHandler);
 const closeEditor=()=>{if(dialog.open)return;dialog.removeEventListener('close',closeEditor);dialog._personnelCloseHandler=null;dialog.classList.remove('personnel-editor');dialog.innerHTML='';editingId=previousId;};
 dialog._personnelCloseHandler=closeEditor;dialog.addEventListener('close',closeEditor);
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;
}
function bindInput(){const picker=$('#profile-picker');picker?.addEventListener('change',()=>{const p=dbState.people.find(p=>p.firstName+' '+p.lastName+' · '+p.lab===picker.value);if(p){editingId=p.id;shell();}});$('#person-form')?.addEventListener('submit',savePersonForm);$('#person-form [name="pl"]')?.addEventListener('change',e=>refreshLearningMatrix($('#person-form'),e.target.value));$('#db-search')?.addEventListener('input',e=>{dbQuery=e.target.value;const at=e.target.selectionStart;renderContent();$('#db-search').focus();$('#db-search').setSelectionRange(at,at);});}
async function savePersonForm(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]');if(!form.reportValidity())return;const data=new FormData(form),v=n=>String(data.get(n)||'').trim();try{button.disabled=true;const first=v('firstName'),last=v('lastName'),code=v('employeeCode');const duplicate=dbState.people.find(p=>p.id!==editingId&&((code&&p.employeeCode===code)||(p.firstName===first&&p.lastName===last)));if(duplicate)throw Error('พบชื่อหรือรหัสพนักงานนี้ในทะเบียนแล้ว: '+duplicate.firstName+' '+duplicate.lastName+' / '+duplicate.lab);const old=dbState.people.find(p=>p.id===editingId)||{};const employment=v('employment'),newY=v('newYear');if(employment==='พนักงานใหม่'&&!newY)throw Error('โปรดระบุปีที่เริ่มเป็นพนักงานใหม่');const readLearning=prefix=>{const fail=(i,message)=>{const item=form.querySelector(`[data-learning-prefix="${prefix}"][data-learning-index="${i}"]`);revealLearningItem(item);throw Error(message);};const cells=[],details=[];for(let i=0;i<(prefix==='core'?NAMES.length:upNames().length);i++){const status=v(prefix+'Status'+i),yr=v(prefix+'Year'+i),date=v(prefix+'Date'+i),evidence=v(prefix+'Evidence'+i);if(status!=='ยังไม่ระบุ'&&!yr)fail(i,'โปรดระบุปีของ '+(prefix==='core'?NAMES[i]:upNames()[i]));if(date&&status!=='สำเร็จ')fail(i,'วันที่เรียนสำเร็จใส่ได้เมื่อสถานะเป็นสำเร็จเท่านั้น: '+(i+1));if(date&&Number(date.slice(0,4))!==Number(yr))fail(i,'ปีและวันที่เรียนสำเร็จไม่ตรงกัน: '+(i+1));if(evidence&&!/^https?:\/\//i.test(evidence))fail(i,'ลิงก์หลักฐานต้องเริ่มด้วย https:// หรือ http://');const oldRaw=(prefix==='core'?dbState.core:dbState.upskill).find(r=>r.id===editingId)?.cells?.[i]||'',oldParsed=parseStatus(oldRaw),oldLabel=oldParsed.complete?'สำเร็จ':oldParsed.plan?'มีแผน':'ยังไม่ระบุ';cells.push(status===oldLabel&&String(oldParsed.year||'')===yr?oldRaw:status==='สำเร็จ'?'complete '+yr:status==='มีแผน'?'plan '+yr:'');details.push({completedDate:date,evidence,note:v(prefix+'Note'+i)});}return{cells,details};};const core=readLearning('core'),up=readLearning('up');const oldEmployment=isExit({...old,remark:old.remark||''})?(/ลาออก/.test(old.remark)?'ลาออก':/ย้าย/.test(old.remark)?'ย้ายสังกัด':'เกษียณ'):/พนักงานใหม่/.test(old.remark||'')?'พนักงานใหม่':'ปฏิบัติงาน';const person={...old,id:editingId||'local-'+TA_UID(),salutation:v('salutation'),employeeCode:code,firstName:first,lastName:last,title:v('title'),pl:v('pl'),functionName:v('functionName'),lab:v('lab'),profileNote:v('profileNote'),remark:old.id&&employment===oldEmployment&&(employment!=='พนักงานใหม่'||String(newYear(old)||'')===newY)?old.remark:employment==='ปฏิบัติงาน'?'':employment==='พนักงานใหม่'?'พนักงานใหม่'+newY:employment==='ย้ายสังกัด'?'ย้ายสังกัด':employment,createdAt:old.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};await TA_DB.save(person,core,up,(editingId?'แก้ไข':'เพิ่ม')+'ข้อมูลบุคลากรและผลพัฒนา / '+person.lab);editingId=person.id;if(form.dataset.personnelModal==='true')$('#detail').close();await hydrateDatabase();toast('บันทึก '+person.firstName+' '+person.lastName+' สำเร็จ'+(window.TA_CLOUD?.enabled?' ลง Google Sheets กลางแล้ว':' ในฐานข้อมูลเครื่องนี้แล้ว'));}catch(e){$('#save-error').textContent=e.message;$('#save-error').scrollIntoView({behavior:'smooth',block:'center'});toast(e.message,{type:'error'});}finally{if(button.isConnected)button.disabled=false;}}
async function backupDatabase(){try{const data=await TA_DB.backup(),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='TA_PULSE_Database_'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('เตรียมไฟล์สำรองฐานข้อมูลแล้ว');}catch(e){toast(e.message,{type:'error'});}}
function addBUDialog(){if(!dbReady)return toast('กรุณารอฐานข้อมูล');$('#detail').innerHTML=`<div class="modal-head"><div><div class="eyebrow">ORGANIZATION</div><h2>เพิ่ม BU / ห้องปฏิบัติการ</h2></div><button class="close" data-action="close" aria-label="ปิดรายละเอียด">×</button></div><form id="bu-form" class="modal-body">${field('ชื่อ BU','buName','','text',true,'maxlength="100" placeholder="เช่น Minburi"')}<p class="modal-note">BU ที่เพิ่มจะปรากฏในทะเบียนรายชื่อและเมนูกรอกข้อมูลทันที</p><button class="btn primary" type="submit">เพิ่ม BU</button></form>`;$('#detail').showModal();$('#bu-form').addEventListener('submit',async e=>{e.preventDefault();const name=e.target.elements.buName.value.trim();if(dbState.bus.some(b=>b.name.toLowerCase()===name.toLowerCase()))return toast('มี BU นี้แล้ว',{type:'warning'});try{await TA_DB.addBU(name);$('#detail').close();await hydrateDatabase();toast('เพิ่ม BU '+name+' แล้ว');}catch(err){toast(err.message,{type:'error'});}});}

const menuFilterState=new Map();
function switchMainMenu(next){if(next===tab)return;menuFilterState.set(tab,{lab,pl,query,year});const saved=menuFilterState.get(next)||{lab:'',pl:'',query:'',year:'2026'};tab=next;lab=saved.lab;pl=saved.pl;query=saved.query;year=saved.year;if(next==='peopleDB'){dbBU=lab;trainingBatch.bu=lab;}}
function matchesPersonnelSearch(p,text){return !text||`${p.firstName} ${p.lastName} ${p.employeeCode||''} ${p.title||''} ${p.lab||''} ${p.functionName||''}`.toLowerCase().includes(text.toLowerCase());}
function setPersonnelBU(value){lab=value;dbBU=value;trainingBatch.bu=value;const control=document.querySelector('#lab');if(control)control.value=value;const clear=document.querySelector('.hub-clear-filter');if(clear)clear.disabled=!(query||lab||pl);}
function resetPersonnelFilters(){setPersonnelBU('');dbQuery='';Object.assign(trainingBatch,{bu:'',pl:'',fn:'',query:'',scope:'relevant',statusFilter:'pending',personFilter:'',selectionFilter:'',onlySelected:false});}
let personnelMode='roster';
const trainingBatch={kind:'up',course:0,selected:new Set(),bu:'',pl:'',fn:'',query:'',scope:'relevant',statusFilter:'pending',personFilter:'',selectionFilter:'',onlySelected:false,status:'สำเร็จ',year:'2026',date:'',evidence:'',note:'',busy:false};
const personnelRosterView=peopleDatabaseView;
peopleDatabaseView=function(){dbBU=lab;trainingBatch.bu=lab;const tabs=`<div class="hub-domain-tabs personnel-tabs" role="group" aria-label="จัดการบุคลากรและผลอบรม">${[['roster','จัดการทะเบียนรายชื่อ','users'],['training','บันทึกผลตามหลักสูตร','book']].map(([key,label,ico])=>`<button type="button" data-personnel-mode="${key}" class="${personnelMode===key?'active':''}" aria-pressed="${personnelMode===key}">${icon(ico)} ${label}</button>`).join('')}</div>`;const roster=personnelRosterView(),marker='<section class="panel"><div class="panel-head">',at=roster.indexOf(marker);if(at<0)return tabs+roster;return roster.slice(0,at)+tabs+(personnelMode==='roster'?roster.slice(at):trainingBatchView());};
function batchRecord(p){return (trainingBatch.kind==='core'?dbState.core:dbState.upskill).find(r=>r.id===p.id)||{cells:Array(trainingBatch.kind==='core'?NAMES.length:upNames().length).fill(''),details:[]};}
function batchRelevant(p){return learningRelevant(trainingBatch.kind,trainingBatch.course,p.pl,batchRecord(p).cells[trainingBatch.course]);}
function batchRows(){const s=trainingBatch;return dbState.people.filter(p=>active(p)&&matchesPersonnelSearch(p,query)&&(!s.personFilter||p.id===s.personFilter)&&(!s.selectionFilter||(s.selectionFilter==='selected'?s.selected.has(p.id):!s.selected.has(p.id)))&&!isExit(p)&&(!s.bu||p.lab===s.bu)&&(!s.pl||p.pl===s.pl)&&(!s.fn||p.functionName===s.fn)&&(!s.query||`${p.firstName} ${p.lastName} ${p.employeeCode||''} ${p.title}`.toLowerCase().includes(s.query.toLowerCase()))&&(!s.onlySelected||s.selected.has(p.id))&&(s.scope==='all'||s.onlySelected||batchRelevant(p))&&(!s.statusFilter||(s.statusFilter==='done'?parseStatus(batchRecord(p).cells[s.course]).complete:s.statusFilter==='plan'?parseStatus(batchRecord(p).cells[s.course]).plan:!parseStatus(batchRecord(p).cells[s.course]).complete)));}
function batchSelect(name,label,values,current){return `<label>${label}<select data-batch-field="${name}">${values.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function batchStatus(p){const v=parseStatus(batchRecord(p).cells[trainingBatch.course]);return (v.complete?'สำเร็จ':v.plan?'มีแผน':'ยังไม่ระบุ')+(v.year?' · '+v.year:'');}
function batchColumnFilter(label,key,values,current){return `<th><details class="batch-column-filter ${current?'is-filtered':''}"><summary>${label} <span>▾</span></summary><div>${batchSelect(key,'เลือกตัวกรอง',[['','ทั้งหมด'],...values],current)}</div></details></th>`;}
function batchTable(){const rows=batchRows(),s=trainingBatch;return `<div class="batch-selection"><span>แสดง ${rows.length} คน · เลือกทั้งหมด <b>${s.selected.size}</b> คน</span><div class="actions"><button type="button" class="btn" data-batch-action="select">เลือกที่แสดง (เว้นผู้สำเร็จแล้ว)</button><button type="button" class="btn" data-batch-action="clear">ล้างที่เลือก</button><button type="button" class="btn" data-batch-action="export">${icon('export')} Export Excel</button><button type="button" class="btn ${s.onlySelected?'primary':''}" data-batch-action="selected">${s.onlySelected?'แสดงรายชื่อทั้งหมด':'ดูเฉพาะที่เลือก'}</button></div></div><div class="table-wrap batch-table"><table data-batch-table><thead><tr><th><label class="batch-all"><input type="checkbox" data-batch-all aria-label="เลือกทั้งหมดตามตัวกรอง" ${rows.length&&rows.every(p=>s.selected.has(p.id))?'checked':''} ${!rows.length?'disabled':''}><span>All</span></label></th>${batchColumnFilter('ชื่อ–นามสกุล','personFilter',dbState.people.filter(active).map(p=>[p.id,p.firstName+' '+p.lastName]),s.personFilter)}${batchColumnFilter('BU / สายงาน','bu',[...new Set(dbState.people.filter(active).map(p=>p.lab))].sort().map(v=>[v,v]),s.bu)}${batchColumnFilter('PL','pl',Object.keys(MATRIX).map(v=>[v,v]),s.pl)}${batchColumnFilter('สถานะเดิม','statusFilter',[['pending','ยังไม่สำเร็จ'],['plan','มีแผน'],['done','สำเร็จแล้ว']],s.statusFilter)}${batchColumnFilter('รายการที่จะบันทึก','selectionFilter',[['selected','เลือกแล้ว'],['unselected','ยังไม่เลือก']],s.selectionFilter)}</tr></thead><tbody>${rows.map(p=>`<tr class="${s.selected.has(p.id)?'batch-picked':''}"><td><input type="checkbox" data-batch-person="${esc(p.id)}" aria-label="เลือก ${esc(p.firstName+' '+p.lastName)}" ${s.selected.has(p.id)?'checked':''}></td><td><strong>${esc(p.firstName+' '+p.lastName)}</strong><small>${esc(p.title)}</small>${!batchRelevant(p)?'<small class="batch-extra">เพิ่มเติมนอกเกณฑ์ / แผนเดิม</small>':''}</td><td>${esc(p.lab)}<small>${esc(p.functionName)}</small></td><td>${esc(p.pl)}</td><td><span class="batch-status ${parseStatus(batchRecord(p).cells[s.course]).complete?'done':parseStatus(batchRecord(p).cells[s.course]).plan?'planned':'empty'}">${esc(batchStatus(p))}</span></td><td>${s.selected.has(p.id)?`<b class="batch-new ${s.status==='สำเร็จ'?'done':'planned'}">${s.status==='สำเร็จ'?'✓':'◷'} ${esc(s.status)} · ${esc(s.year)}</b>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty"><strong>ไม่พบรายชื่อตามตัวกรองนี้</strong><p>ลองล้างตัวกรองเพื่อดูบุคลากรที่เลือกได้</p><button type="button" class="btn filter-reset" data-batch-action="reset-filters"><span class="filter-reset-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/></svg></span><span>ล้างตัวกรองรายชื่อ</span></button></td></tr>'}</tbody></table></div><div class="batch-savebar"><span>เลือก <b>${s.selected.size} คน</b> · ${esc((s.kind==='core'?NAMES:upNames())[s.course])}</span><button class="btn primary" type="submit" ${!s.selected.size?'disabled':''}>ตรวจสอบก่อนบันทึก ${s.selected.size} คน</button></div>`;}
function trainingBatchView(){if(!dbReady)return '<div class="empty">กำลังเตรียมข้อมูล…</div>';const s=trainingBatch,options=key=>[['','ทั้งหมด'],...[...new Set(dbState.people.filter(active).map(p=>p[key]).filter(Boolean))].sort().map(v=>[v,v])];return `<section class="panel batch-editor"><div class="panel-head"><div><h3>บันทึกผลการอบรมตามหลักสูตร</h3><p>เลือกหลักสูตร กรอกข้อมูลร่วม แล้วติ๊กรายชื่อผู้เรียน · บันทึกเฉพาะคนที่เลือก</p></div></div><form id="training-batch-form"><section class="batch-step batch-step-course"><div class="batch-step-title"><span>01</span><div><h4>เลือกหลักสูตร</h4><p>เลือกเรื่องที่จะบันทึกให้ผู้เรียนกลุ่มนี้</p></div></div><div class="batch-course-grid">${batchSelect('kind','ประเภท',[['core','สมรรถนะหลัก'],['up','Upskilling']],s.kind)}${batchSelect('course','หลักสูตร',(s.kind==='core'?NAMES:upNames()).map((n,i)=>[i,n]),s.course)}</div></section><section class="batch-step batch-step-result"><div class="batch-step-title"><span>02</span><div><h4>กรอกผลร่วมกัน</h4><p>ข้อมูลนี้ใช้กับทุกรายชื่อที่ติ๊กเลือก</p></div></div><div class="batch-common">${batchSelect('status','ผลที่จะบันทึก',[['สำเร็จ','สำเร็จ'],['มีแผน','มีแผน']],s.status)}<label>ปี (ค.ศ.)<input data-batch-field="year" type="number" min="2000" max="2100" required value="${esc(s.year)}"></label><label>วันที่เรียนสำเร็จ<input data-batch-field="date" type="date" value="${esc(s.date)}" ${s.status!=='สำเร็จ'?'disabled':''}></label></div><details class="batch-optional" ${s.evidence||s.note?'open':''}><summary>＋ เพิ่มหลักฐาน / ชื่อรุ่น / หมายเหตุ <small>ไม่บังคับ</small></summary><div class="batch-optional-fields"><label>ลิงก์หลักฐานร่วม<input data-batch-field="evidence" type="url" placeholder="https://…" value="${esc(s.evidence)}"></label><label>ชื่อรุ่น / หมายเหตุร่วม<input data-batch-field="note" maxlength="1000" value="${esc(s.note)}" placeholder="ไม่ระบุ = เก็บหมายเหตุเดิม"></label></div></details><p class="batch-hint">ช่องหลักฐานและหมายเหตุที่เว้นว่างจะเก็บข้อมูลเดิม · เลือกผู้สำเร็จแล้วด้วยตนเองได้หากต้องการปรับผล</p></section><section class="batch-step batch-step-people"><div class="batch-step-title"><span>03</span><div><h4>เลือกรายชื่อผู้เรียน</h4><p>ค้นหาและกรอง แล้วติ๊กเฉพาะคนที่จะบันทึกผล</p></div></div><div class="batch-filters"><label>ค้นหารายชื่อ<input data-batch-field="query" placeholder="ชื่อ / รหัส / ตำแหน่ง" value="${esc(s.query)}"></label>${batchSelect('bu','BU',options('lab'),s.bu)}${batchSelect('fn','สายงาน',options('functionName'),s.fn)}${batchSelect('pl','PL',options('pl'),s.pl)}${batchSelect('scope','กลุ่มรายชื่อ',[['relevant','ตาม Matrix / มีแผนหรือผลเรียน'],['all','บุคลากรทั้งหมด']],s.scope)}${batchSelect('statusFilter','สถานะเดิม',[['','ทุกสถานะ'],['pending','ยังไม่สำเร็จ'],['plan','มีแผน'],['done','สำเร็จแล้ว']],s.statusFilter)}</div><div id="batch-list">${batchTable()}</div><p id="batch-feedback" role="status"></p></section></form></section>`;}
function refreshBatchList(){const el=$('#batch-list');if(el)el.innerHTML=batchTable();const all=document.querySelector('[data-batch-all]'),rows=batchRows();if(all)all.indeterminate=rows.some(p=>trainingBatch.selected.has(p.id))&&!rows.every(p=>trainingBatch.selected.has(p.id));document.querySelectorAll('#training-batch-form select[data-batch-field]').forEach(select=>select.value=String(trainingBatch[select.dataset.batchField]));}
function batchChanges(){const s=trainingBatch;if(!s.selected.size)throw Error('กรุณาเลือกรายชื่อ');if(!/^\d{4}$/.test(s.year)||+s.year<2000||+s.year>2100)throw Error('กรุณาระบุปี ค.ศ. 2000–2100');if(s.date&&s.status==='สำเร็จ'&&s.date.slice(0,4)!==s.year)throw Error('ปีและวันที่เรียนสำเร็จต้องตรงกัน');if(s.evidence&&!/^https?:\/\//i.test(s.evidence))throw Error('ลิงก์หลักฐานต้องเริ่มด้วย http:// หรือ https://');return dbState.people.filter(p=>active(p)&&s.selected.has(p.id)).map(p=>{const clone=(r,count)=>padLearning(r,count);const core=clone(dbState.core.find(r=>r.id===p.id),NAMES.length),up=clone(dbState.upskill.find(r=>r.id===p.id),upNames().length),target=s.kind==='core'?core:up,old=target.details[s.course]||{};target.cells[s.course]=(s.status==='สำเร็จ'?'complete ':'plan ')+s.year;target.details[s.course]={...old,completedDate:s.status==='สำเร็จ'?(s.date||(old.completedDate?.slice(0,4)===s.year?old.completedDate:'')):'',evidence:s.evidence||old.evidence||'',note:s.note||old.note||''};return {person:{...p,updatedAt:new Date().toISOString()},core,up,before:batchStatus(p)};});}
function reviewTrainingBatch(){try{const changes=batchChanges(),s=trainingBatch,d=$('#detail');d.innerHTML=`<div class="modal-head"><div><h2>ตรวจสอบการบันทึก ${changes.length} คน</h2><p>${esc((s.kind==='core'?NAMES:upNames())[s.course])} · ${esc(s.status)} ${esc(s.year)}</p></div><button class="close" data-action="close" aria-label="ปิด">×</button></div><div class="modal-body"><p>วันที่: ${esc(s.date||'ไม่ระบุ')} · หลักฐาน: ${esc(s.evidence||'เก็บข้อมูลเดิม')}</p><div class="table-wrap"><table data-batch-table><thead><tr><th>บุคลากร</th><th>BU</th><th>เดิม</th><th>ใหม่</th></tr></thead><tbody>${changes.map(c=>`<tr><td>${esc(c.person.firstName+' '+c.person.lastName)}</td><td>${esc(c.person.lab)}</td><td>${esc(c.before)}</td><td>${esc(s.status+' · '+s.year)}</td></tr>`).join('')}</tbody></table></div><p id="batch-save-result" role="status"></p><div class="actions"><button class="btn" data-action="close">กลับไปแก้ไข</button><button class="btn primary" id="batch-confirm">ยืนยันบันทึก ${changes.length} คน</button></div></div>`;d.showModal();$('#batch-confirm').addEventListener('click',()=>commitTrainingBatch(changes));}catch(e){$('#batch-feedback').textContent=e.message;toast(e.message,{type:'warning'});}}
async function commitTrainingBatch(changes){if(trainingBatch.busy)return;trainingBatch.busy=true;const d=$('#detail'),result=$('#batch-save-result');d.querySelectorAll('button').forEach(b=>b.disabled=true);const block=e=>e.preventDefault();d.addEventListener('cancel',block);let saved=0;const batchId=TA_UID(),title=(trainingBatch.kind==='core'?NAMES:upNames())[trainingBatch.course];try{for(const c of changes){await TA_DB.save(c.person,c.core,c.up,`อบรมกลุ่ม ${batchId} / ${title} / ${trainingBatch.status} ${trainingBatch.year}`);trainingBatch.selected.delete(c.person.id);saved++;result.textContent=`บันทึกแล้ว ${saved} / ${changes.length} คน`; }await hydrateDatabase();d.close();toast(`บันทึกผลอบรม ${saved} คนแล้ว`);}catch(e){result.textContent=`บันทึกสำเร็จ ${saved} คน · หยุดเมื่อพบข้อผิดพลาด: ${e.message} · ปิดหน้าต่างเพื่อตรวจรายการที่เหลือก่อนลองใหม่`;toast(result.textContent,{type:'error'});try{await hydrateDatabase();}catch(_){} }finally{trainingBatch.busy=false;d.removeEventListener('cancel',block);d.querySelectorAll('button').forEach(b=>b.disabled=false);const confirm=$('#batch-confirm');if(confirm)confirm.disabled=true;}}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-personnel-mode]');if(mode){personnelMode=mode.dataset.personnelMode;trainingBatch.bu=dbBU;renderContent();document.querySelector('.personnel-tabs')?.scrollIntoView({block:'start',behavior:'smooth'});return;}const action=e.target.closest('[data-batch-action]');if(!action)return;const s=trainingBatch;switch(action.dataset.batchAction){case 'reset-filters':setPersonnelBU('');s.pl='';s.fn='';s.query='';s.scope='all';s.statusFilter='';s.personFilter='';s.selectionFilter='';s.onlySelected=false;renderContent();return;case 'export':{const rows=batchRows().map(p=>({'เลือก':s.selected.has(p.id)?'✓':'','บุคลากร':p.firstName+' '+p.lastName,'BU':p.lab,'สายงาน':p.functionName,'PL':p.pl,'หลักสูตร':(s.kind==='core'?NAMES:upNames())[s.course],'สถานะเดิม':batchStatus(p),'ผลที่จะบันทึก':s.selected.has(p.id)?s.status+' '+s.year:''}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'รายชื่ออบรม');XLSX.writeFile(wb,'TA_Training_Selection.xlsx');return;}case 'select':batchRows().filter(p=>!parseStatus(batchRecord(p).cells[s.course]).complete).forEach(p=>s.selected.add(p.id));break;case 'clear':s.selected.clear();break;case 'selected':s.onlySelected=!s.onlySelected;break;}refreshBatchList();});
document.addEventListener('change',e=>{const t=e.target,s=trainingBatch;if(t.matches('[data-batch-all]')){batchRows().forEach(p=>t.checked?s.selected.add(p.id):s.selected.delete(p.id));refreshBatchList();return;}if(t.matches('[data-batch-person]')){t.checked?s.selected.add(t.dataset.batchPerson):s.selected.delete(t.dataset.batchPerson);refreshBatchList();return;}if(!t.matches('[data-batch-field]'))return;const key=t.dataset.batchField;s[key]=key==='course'?+t.value:t.value;if(key==='bu'){setPersonnelBU(t.value);renderContent();return;}if(key==='kind'||key==='course'){s.selected.clear();s.onlySelected=false;if(key==='kind')s.course=0;renderContent();}else if(key==='status'){if(s.status!=='สำเร็จ')s.date='';renderContent();}else refreshBatchList();});
document.addEventListener('input',e=>{const t=e.target;if(!t.matches('[data-batch-field]')||t.tagName==='SELECT')return;trainingBatch[t.dataset.batchField]=t.value;refreshBatchList();});
document.addEventListener('submit',e=>{if(e.target.id==='training-batch-form'){e.preventDefault();reviewTrainingBatch();}});

window.addEventListener('beforeprint',()=>{savedPage=page;printing=true;renderContent();});window.addEventListener('afterprint',()=>{printing=false;page=savedPage;renderContent();});

document.addEventListener('click',e=>{const bu=e.target.closest('[data-bu]');if(bu){setPersonnelBU(bu.dataset.bu);renderContent();return;}const edit=e.target.closest('[data-edit]');if(edit){if(tab!=='peopleDB'){tab='peopleDB';shell();}openPersonnelDialog(edit.dataset.edit);return;}const fc=e.target.closest('[data-focus]');if(fc){tab='followup';status=fc.dataset.focus;page=0;shell();window.scrollTo(0,0);return;}const sk=e.target.closest('[data-skill]');if(sk){skillDetail(+sk.dataset.skill);return;}const sp=e.target.closest('[data-skill-person]');if(sp){$('#detail').close();detail(sp.dataset.skillPerson);return;}const ch=e.target.closest('[data-chart]');if(ch){chartMode=ch.dataset.chart;renderContent();return;}const nav=e.target.closest('[data-tab]');if(nav){switchMainMenu(nav.dataset.tab==='input'?'peopleDB':nav.dataset.tab);page=0;status='all';document.body.classList.remove('menu');shell();window.scrollTo(0,0);return;}const l=e.target.closest('[data-lab]');if(l){lab=l.dataset.lab;tab='directory';page=0;shell();return;}const s=e.target.closest('[data-status]');if(s){status=s.dataset.status;page=0;renderContent();return;}const p=e.target.closest('[data-person]');if(p){detail(p.dataset.person);return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='new-person'){if(tab!=='peopleDB'){tab='peopleDB';shell();}openPersonnelDialog('');return;}if(action==='backup-db')backupDatabase();if(action==='restore-db')$('#restore-upload').click();if(action==='add-bu')addBUDialog();if(action==='presentation'){document.body.classList.toggle('presentation');toast(document.body.classList.contains('presentation')?'เปิดโหมดนำเสนอ · กด Esc เพื่อกลับ':'กลับสู่โหมดปกติ');}if(action==='menu')document.body.classList.toggle('menu');if(action==='close')$('#detail').close();if(action==='reset'){lab='';pl='';year='2026';query='';status='all';page=0;shell();}if(action==='prev'){page=Math.max(0,page-1);renderContent();}if(action==='next'){page++;renderContent();}if(action==='print')window.print();if(action==='export'){try{exportData();}catch(err){toast('ส่งออกไม่สำเร็จ: '+err.message);}}if(action==='import')$('#upload').click();if(action==='refresh')refresh();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('presentation');});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#upload').addEventListener('change',e=>importFile(e.target.files[0]));
function showCloudLogin(message=''){const configured=!!window.TA_CONFIG.apiUrl;$('#app').innerHTML=`<div class="login-page"><section class="login-content"><div class="login-box"><h2>เชื่อมต่อฐานข้อมูล Google Sheets</h2><p>${configured?'ยังอ่านข้อมูลไม่ได้ กรุณาลองเชื่อมต่ออีกครั้ง':'ยังไม่ได้ตั้งค่า URL Apps Script ใน config.js'}</p><div class="login-error" role="alert">${esc(message)}</div><button class="btn primary" id="cloud-retry" ${configured?'':'disabled'}>ลองเชื่อมต่ออีกครั้ง</button></div></section></div>`;if(message)toast(message,{type:'error'});$('#cloud-retry').addEventListener('click',async e=>{e.target.disabled=true;try{await hydrateDatabase();}catch(err){showCloudLogin(err.message);}});}
try{if(window.TA_CLOUD?.enabled){hydrateDatabase().catch(e=>showCloudLogin(e.message));}else if(typeof google!=='undefined'&&google.script?.run){sourceLabel='Google Sheets';shell();refresh();}else{setSource(source,sourceLabel);bootstrapDatabase();}}catch(e){$('#app').innerHTML=`<div class="empty">เปิดข้อมูลไม่สำเร็จ: ${esc(e.message)}</div>`;}

$('#restore-upload')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!await window.TA_NOTIFY.confirm('กู้คืนฐานข้อมูลจากไฟล์นี้จะใช้แทนข้อมูลในเครื่องปัจจุบัน โปรดสำรอง JSON ปัจจุบันไว้ก่อน ต้องการกู้คืนหรือไม่?'))return;await TA_DB.restore(data);await hydrateDatabase();toast('กู้คืนฐานข้อมูลเรียบร้อย');}catch(err){toast('กู้คืนไม่สำเร็จ: '+err.message);}finally{e.target.value='';}});
